def distill_playbook(trajectories):
    playbook = {}
    for traj in trajectories:
        for (state, action, reward) in traj:
            playbook.setdefault(state, []).append((action, reward))
    return playbook

def shared_world_consistency(env_cons, upd_cons, id_cons, lam=None):
    lam = lam or [1/3, 1/3, 1/3]
    return lam[0]*env_cons + lam[1]*upd_cons + lam[2]*id_cons

def feasible_future_mass(traj_samples, choose_block, safe_flags):
    n = len(traj_samples)
    total = 0.0
    for tr, safe in zip(traj_samples, safe_flags):
        if safe and choose_block(tr) is not None:
            total += 1.0
    return total / max(n, 1)

def vics_g_rerank(candidates, est_mass, alarm):
    if not alarm:
        return candidates[0]
    best = max(candidates, key=lambda b: est_mass[b])
    return best
